SELECT
    s.owner_user AS username,
    MAX(u.real_name) AS real_name,
    COUNT(*) AS count
FROM work_order_step s
JOIN work_order w ON w.id = s.work_order_id AND w.tenant_id = #{tenantId} AND w.deleted = 0 AND w.task_type = #{taskType}
LEFT JOIN sys_user u ON u.username = s.owner_user AND u.tenant_id = #{tenantId} AND u.deleted = 0
WHERE s.tenant_id = #{tenantId}
  AND s.step_code = #{stepCode}
  AND s.status = 'DONE'
  AND s.complete_time IS NOT NULL
  AND s.complete_time >= #{start}
  AND s.complete_time < #{end}
  AND s.owner_user IS NOT NULL
GROUP BY s.owner_user
ORDER BY count DESC, MIN(s.complete_time) ASC
